import React from 'react';
import { BrowserRouter, Routes, Route } from "react-router-dom";
import './main.css';
import ProductDetails from './ProductDetails';
import Report from './Report';
import Inventory from './Inventory';
import Suppliers from './Suppliers';
import AddSupplierForm from './AddSupplierForm';
import Notifications from './Notifications';
import Orders from './Orders';
import OrderDetails from './OrderDetails';
import Employees from './Employees';
import AddEmployeeForm from './AddEmployeeForm';
import Settings from './Settings';
import EditSupplierForm from './EditSupplierForm';
import EditInventoryForm from './EditInventoryForm';
import AddProductForm from './AddProductForm';
import SupplierInfo from './SupplierInfo';
import WarehouseInfo from './WarehouseInfo';
import Support from './Support';
import WarehousesList from './WarehousesList';
import EmployeeDetails from './EmployeeDetails';

function Main({authorisedUser, getSuppliers, suppliers, addSupplier, deleteSupplier, updateSupplier, getProducts, updateProduct, addProduct, deleteProduct, getWarehouseInfo, getEmployees, updateEmployee, updateAddress, deleteEmployee, getEmployeeById, addAddress, addEmployee}) {
  
  if (Object.keys(authorisedUser).length === 0) {
    return null;
} 
  return (
    <div className="main-content">
      <Routes>
        <Route path="/inventory" element={ <Inventory getProducts={getProducts} updateProduct={updateProduct} getSuppliers={getSuppliers} deleteProduct={deleteProduct} /> } />
        <Route path="/" element={ <Inventory getProducts={getProducts} updateProduct={updateProduct} getSuppliers={getSuppliers} deleteProduct={deleteProduct} /> } />
        <Route path="/inventory/product-details/:id" element={ <ProductDetails /> } />
        <Route path='/inventory/edit/:id' element={<EditInventoryForm getProducts={getProducts} updateProduct={updateProduct} />} />
        <Route path='/inventory/add-product' element={ <AddProductForm addProduct={addProduct} getSuppliers={getSuppliers}/> } />
        <Route path='/warehouses' element={ <WarehousesList /> } />
        <Route path='/warehouses/warehouse-info/:id' element={ <WarehouseInfo getWarehouseInfo={getWarehouseInfo} /> } />
        <Route path="/report" element={ <Report /> } />
        <Route path='/suppliers' element={ <Suppliers getSuppliers={getSuppliers} suppliers={suppliers} deleteSupplier={deleteSupplier} /> } />
        <Route path= '/suppliers/info/:id' element={ <SupplierInfo getProducts={getProducts} getSuppliers={getSuppliers} /> } />
        <Route path='/suppliers/add-supplier' element={ <AddSupplierForm addSupplier={addSupplier}/> } />
        <Route path='/suppliers/edit/:id' element={<EditSupplierForm getSuppliers={getSuppliers} updateSupplier={updateSupplier} /> } />
        <Route path='/employees' element={ <Employees getEmployees = {getEmployees} updateEmployee = {updateEmployee} updateAddress = {updateAddress} deleteEmployee = {deleteEmployee} /> } />
        <Route path='/employees/add-employee' element={ <AddEmployeeForm addAddress = {addAddress} addEmployee = {addEmployee} /> } />
        <Route path ='/employees/info/:id' element={<EmployeeDetails getEmployeeById = {getEmployeeById} /> } />
        <Route path='/notifications' element={ <Notifications />} />
        <Route path='/orders' element={ <Orders /> } />
        <Route path='/orders/order-details/:id' element={ <OrderDetails /> } />
        <Route path='/settings' element={ <Settings authorisedUser={authorisedUser} getEmployeeById = {getEmployeeById} updateEmployee = {updateEmployee} updateAddress = {updateAddress}/>  } />
        <Route path='/support' element={ <Support /> } />

      </Routes>
      
    </div>

  );
}

export default Main;
